head.script:
scwin.onpageload = function() {
	scwin.data1 = [
		"0", "(주)A", 1,
		"0", "(주)A", 2,
		"0", "*A", 3,
		"0", "&B", 4,
		"0", "%C", 5,
		"0", "^A", 6,
		"0", "#B", 7,
		"0", "$C", 8,
		"0", "-A", 9,
		"0", "[주]B", 10,
		"0", "{주}C", 11,
		"0", "::A", 12,
		"0", "B", 13,
		"0", "C", 14,
		"0", "A", 15,
		"0", "B", 16,
		"0", "C", 17,
		"0", "A", 18,
		"0", "B", 19,
		"0", "C", 20,
		"0", "A", 21,
		"0", "B", 22,
		"0", "C", 23,
		"0", "A", 24,
		"0", "B", 25,
		"0", "C", 26,
		"0", "A", 27,
		"0", "B", 28,
		"0", "C", 29,
		"0", "A", 30
	];
	dataList1.setData(scwin.data1.slice(0));
}
scwin.grid1_ongroupby = function(options) {
	options.closeGroup = true;
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
}
scwin.trigger4_onclick = function(e) {
	dataList1.setColumnFilter({
		type: "row",
		colIndex: "col3",
		key: "4",
		condition: "<",
		columnDataType: "number"
	});
};
scwin.checkVal1 = function() {
	return ((j) => j.length ? j : $('.mf_w2grid_customFilter_list_listColumn_checkbox'))($('.w2grid_customFilter_list_listColumn_checkbox'))[2].checked == true;
}
scwin.checkVal2 = function() {
	return ((j) => j.length ? j : $('.mf_w2grid_customFilter_list_listColumn_checkbox'))($('.w2grid_customFilter_list_listColumn_checkbox'))[13].checked == true;
}
scwin.checkVal3 = function() {
	return ((j) => j.length ? j : $('.mf_w2grid_customFilter_list_listColumn_checkbox'))($('.w2grid_customFilter_list_listColumn_checkbox'))[24].checked == true;
}
